fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (idx, &value) in nums.iter().enumerate() {
        if value == target {
            // Found the first occurrence; return its index as i32.
            return idx as i32;
        }
    }
    // Not found; return a negative value.
    -1
}

